import copy


def attach_labels(hierarchy, facts):
    if not isinstance(facts, dict):
        raise TypeError("facts must be a dictionary")
    for name, values in facts.items():
        if not isinstance(name, str):
            raise TypeError("fact names must be strings")
        if not isinstance(values, dict):
            raise TypeError("fact values must be dictionaries")
        for key, value in values.items():
            if not isinstance(key, str) or not isinstance(value, str):
                raise TypeError("fact keys and values must be strings")

    active = set()

    def visit(node):
        if not isinstance(node, dict):
            raise TypeError("nodes must be dictionaries")
        if set(node) != {"name", "children"}:
            raise ValueError("node fields are invalid")
        name = node["name"]
        if name is not None and not isinstance(name, str):
            raise TypeError("node names must be strings or None")
        if not isinstance(node["children"], list):
            raise TypeError("children must be a list")
        identity = id(node)
        if identity in active:
            raise ValueError("hierarchy contains a cycle")
        active.add(identity)
        source = facts.get(name, {}) if name is not None else {}
        attributes = {
            key: copy.deepcopy(source[key])
            for key in sorted(source)
        }
        result = {
            "name": copy.deepcopy(name),
            "children": [visit(child) for child in node["children"]],
            "attributes": attributes,
        }
        active.remove(identity)
        return result

    return visit(hierarchy)

